CREATE TABLE attendance_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), employee_id UUID NOT NULL REFERENCES employees(id), attendance_date DATE NOT NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('PRESENT','ABSENT','LATE','HALF_DAY')), check_in TIMESTAMPTZ, check_out TIMESTAMPTZ, notes VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(employee_id, attendance_date));
CREATE TABLE leave_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), employee_id UUID NOT NULL REFERENCES employees(id), leave_type VARCHAR(30) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, reason VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', reviewed_by UUID REFERENCES users(id), reviewed_at TIMESTAMPTZ);
CREATE TABLE eod_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), employee_id UUID NOT NULL REFERENCES employees(id), report_date DATE NOT NULL, summary VARCHAR(3000) NOT NULL, blockers VARCHAR(2000), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', submitted_at TIMESTAMPTZ, reviewed_by UUID REFERENCES users(id), UNIQUE(employee_id, report_date));
CREATE INDEX idx_attendance_org ON attendance_records(organization_id); CREATE INDEX idx_leave_org ON leave_requests(organization_id); CREATE INDEX idx_eod_org ON eod_reports(organization_id);
